      "field name": "Name"
    },
    {
      "type": "raw",
      "raw field": "value",
      "field name": "ID"
    },
    {
      "type": "raw",
      "raw field": "group",
      "field name": "Page"
    },
    {
      "type": "raw",
      "raw field": "link",
      "field name": "Open"
    }
  ],
  "top rows": [
    "Name",
    "ID",
    "Page",
    "Open"
  ],
  "column formatting": {
    "Open": {
      "type": [
        "link"
      ],
      "link type": "button",
